// Package emitter generates output files from the Schema IR.
package emitter

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/codewandler/compschema/internal/ir"
	"github.com/codewandler/compschema/internal/uniongen"
)

// isAnyType returns true if the type is an interface{}/any alias
// that cannot have methods defined on it.
func isAnyType(t *ir.Type) bool {
	return t.Kind == ir.KindScalar && t.ScalarType == "any"
}

// isWrapperType returns true if the type is a primitive wrapper struct
// generated by uniongen (e.g. `type FooString struct { Value string }`).
// These types have custom MarshalJSON that serializes as the inner value,
// so their JSON form doesn't match the struct form.
func isWrapperType(t *ir.Type) bool {
	if t.Kind != ir.KindStruct || len(t.Fields) != 1 {
		return false
	}
	return t.Fields[0].JSONName == "Value" || t.Fields[0].JSONName == "value"
}

// isScalarWrapper returns true if the wrapper type wraps a scalar (string, number,
// boolean, integer) rather than a complex type (struct, union, list, map).
func isScalarWrapper(t *ir.Type) bool {
	if !isWrapperType(t) {
		return false
	}
	f := t.Fields[0]
	if f.Type.Inline != nil {
		k := f.Type.Inline.Kind
		return k == ir.KindScalar || k == ir.KindEnum
	}
	// Named type reference — not a scalar wrapper (could be a struct, union, etc.).
	// A named scalar type (e.g., type MyString string) would be KindScalar or KindEnum
	// in the IR, but its reference here is by name, so we can't determine the kind
	// without looking it up. Conservative: return false.
	return false
}

// codegenResolver implements uniongen.TypeResolver for the codegen path.
// In the codegen path, IR type names ARE Go names (from go/types analysis),
// but JSON field names need conversion to Go field names.
type codegenResolver struct {
	pkg    *ir.Package
	fields map[string]string // jsonName → goFieldName lookup
}

// newCodegenResolver creates a resolver pre-populated with field name mappings
// from all struct types in the package.
func newCodegenResolver(pkg *ir.Package) *codegenResolver {
	fields := make(map[string]string)
	for _, name := range pkg.Order {
		t := pkg.Types[name]
		if t.Kind != ir.KindStruct {
			continue
		}
		for _, f := range t.Fields {
			fields[f.JSONName] = f.Name
		}
	}
	return &codegenResolver{pkg: pkg, fields: fields}
}

func (r *codegenResolver) GoName(name string) string {
	// First check if it's a JSON field name that maps to a Go field name.
	if goName, ok := r.fields[name]; ok {
		return goName
	}
	// Otherwise it's already a Go name (type names from the analyzer).
	return name
}
func (r *codegenResolver) GoType(ref *ir.TypeRef) string { return fieldGoTypeFromRef(*ref, r.pkg) }
func (r *codegenResolver) Comment(desc string) string    { return desc }
func (r *codegenResolver) IsStruct(name string) bool {
	if t, ok := r.pkg.Types[name]; ok {
		return t.Kind == ir.KindStruct
	}
	return false
}

// emitCodegenUnmarshalJSON generates a custom UnmarshalJSON for structs with
// union-typed fields. Without this, json.Unmarshal fails because it can't
// unmarshal into interface fields.
//
// The generated method uses Decode{UnionName} (from the codegen output) to
// dispatch each union field, falling back to Unmarshal{UnionName} if the
// types were generated by the importer.
func emitCodegenUnmarshalJSON(b *strings.Builder, name string, t *ir.Type, pkg *ir.Package, r uniongen.TypeResolver, unionTypes map[string]bool) {
	uniongen.EmitStructUnmarshalJSON(b, name, t, pkg, r, unionTypes)
}

// EmitOptions controls optional features of the JSON Schema emitter.
type EmitOptions struct {
	Examples     bool // add "examples" arrays to $defs
	Constructors bool // generate NewT() constructors for struct types
}

// JSONSchema emits a JSON Schema draft 2020-12 document from an IR Package.
// Single-use enum and scalar $defs are inlined at their reference site.
func JSONSchema(pkg *ir.Package) ([]byte, map[string]bool, error) {
	return JSONSchemaWithOptions(pkg, EmitOptions{})
}

// JSONSchemaWithOptions emits a JSON Schema with configurable options.
func JSONSchemaWithOptions(pkg *ir.Package, opts EmitOptions) ([]byte, map[string]bool, error) {
	defs := make(map[string]any)

	for _, name := range pkg.Order {
		t := pkg.Types[name]
		defs[name] = typeToSchema(t, true)
	}

	// Add examples before inlining so inlined types carry their examples.
	if opts.Examples {
		AddExamples(defs, pkg)
	}

	// Inline single-use trivial $defs.
	inlined := inlineDefs(defs, pkg)

	doc := map[string]any{
		"$schema": "https://json-schema.org/draft/2020-12/schema",
		"$defs":   defs,
	}

	data, err := json.MarshalIndent(doc, "", "  ")
	return data, inlined, err
}

// inlineDefs replaces single-use $ref to trivial types (enums, scalars)
// with their inline schema, and removes them from $defs.
func inlineDefs(defs map[string]any, pkg *ir.Package) map[string]bool {
	refCounts := make(map[string]int)
	countRefs(defs, refCounts)

	inlined := make(map[string]bool)
	for name, count := range refCounts {
		if count != 1 {
			continue
		}
		t, ok := pkg.Types[name]
		if !ok {
			continue
		}
		if t.Kind == ir.KindEnum || t.Kind == ir.KindScalar {
			inlined[name] = true
		}
	}

	for name := range inlined {
		schema := defs[name]
		replaceRef(defs, "#/$defs/"+name, schema)
		delete(defs, name)
	}

	return inlined
}

// countRefs counts how many times each $def name appears as a $ref target.
func countRefs(v any, counts map[string]int) {
	switch val := v.(type) {
	case map[string]any:
		if ref, ok := val["$ref"]; ok {
			if s, ok := ref.(string); ok && strings.HasPrefix(s, "#/$defs/") {
				name := strings.TrimPrefix(s, "#/$defs/")
				counts[name]++
			}
		}
		for _, child := range val {
			countRefs(child, counts)
		}
	case []any:
		for _, child := range val {
			countRefs(child, counts)
		}
	}
}

// replaceRef recursively replaces {"$ref": target} with the inline schema.
// If the object has additional keys alongside $ref (e.g. description), those
// are merged into the replacement.
func replaceRef(v any, target string, replacement any) {
	switch val := v.(type) {
	case map[string]any:
		for k, child := range val {
			if childMap, ok := child.(map[string]any); ok {
				if ref, ok := childMap["$ref"]; ok && ref == target {
					// Merge: start with replacement, add extra keys from the ref object.
					if replMap, ok := replacement.(map[string]any); ok {
						merged := make(map[string]any, len(replMap)+len(childMap))
						for rk, rv := range replMap {
							merged[rk] = rv
						}
						for ck, cv := range childMap {
							if ck != "$ref" {
								merged[ck] = cv
							}
						}
						val[k] = merged
					} else {
						val[k] = replacement
					}
					continue
				}
			}
			replaceRef(child, target, replacement)
		}
	case []any:
		for i, child := range val {
			if childMap, ok := child.(map[string]any); ok {
				if ref, ok := childMap["$ref"]; ok && ref == target {
					if replMap, ok := replacement.(map[string]any); ok {
						merged := make(map[string]any, len(replMap)+len(childMap))
						for rk, rv := range replMap {
							merged[rk] = rv
						}
						for ck, cv := range childMap {
							if ck != "$ref" {
								merged[ck] = cv
							}
						}
						val[i] = merged
					} else {
						val[i] = replacement
					}
					continue
				}
			}
			replaceRef(child, target, replacement)
		}
	}
}

// typeToSchema converts an IR Type into a JSON Schema map.
func typeToSchema(t *ir.Type, topLevel bool) map[string]any {
	if t == nil {
		return map[string]any{}
	}

	s := make(map[string]any)

	if t.Description != "" && topLevel {
		s["description"] = t.Description
	}

	switch t.Kind {
	case ir.KindStruct:
		// Wrapper types (single "Value" field) that wrap scalars marshal as their
		// inner value, not as a JSON object. Emit the inner type's schema directly.
		if isWrapperType(t) && isScalarWrapper(t) {
			f := t.Fields[0]
			inner := typeRefToSchema(f.Type)
			if t.Description != "" && topLevel {
				inner["description"] = t.Description
			}
			if topLevel && t.Name != "" {
				inner["title"] = t.Name
			}
			return inner
		}
		s["type"] = "object"
		if topLevel && t.Name != "" {
			s["title"] = t.Name
		}
		props := make(map[string]any)
		var required []string
		for _, f := range t.Fields {
			prop := typeRefToSchema(f.Type)
			if f.Description != "" {
				prop["description"] = f.Description
			}
			for _, c := range f.Constraints {
				prop[c.Keyword] = c.Value
			}
			props[f.JSONName] = prop
			if f.Required {
				required = append(required, f.JSONName)
			}
		}
		if len(props) > 0 {
			s["properties"] = props
		}
		if len(required) > 0 {
			s["required"] = required
		}
		s["additionalProperties"] = false

	case ir.KindEnum:
		s["type"] = t.EnumType
		s["enum"] = t.EnumValues
		if topLevel && t.Name != "" {
			s["title"] = t.Name
		}

	case ir.KindUnion:
		variants := make([]any, 0, len(t.Variants))
		for _, v := range t.Variants {
			variants = append(variants, typeRefToSchema(v.TypeRef))
		}
		s["oneOf"] = variants
		if t.Discriminator != "" {
			s["discriminator"] = map[string]any{
				"propertyName": t.Discriminator,
			}
		}

	case ir.KindScalar:
		if t.ScalarType == "any" {
			// interface{} — accepts any JSON value.
			return s
		}
		scalarType := t.ScalarType
		// Normalize Go-specific integer types to JSON Schema "integer".
		switch scalarType {
		case "int", "int8", "int16", "int32", "int64":
			scalarType = "integer"
		}
		s["type"] = scalarType

	case ir.KindList:
		s["type"] = "array"
		if t.Items != nil {
			s["items"] = typeRefToSchema(*t.Items)
		}

	case ir.KindMap:
		s["type"] = "object"
		if t.MapValue != nil {
			s["additionalProperties"] = typeRefToSchema(*t.MapValue)
		}

	case ir.KindNullable:
		if t.Inner != nil {
			inner := typeRefToSchema(*t.Inner)
			// Merge null into type.
			if typ, ok := inner["type"]; ok {
				inner["type"] = []any{typ, "null"}
			} else if ref, ok := inner["$ref"]; ok {
				// Nullable $ref → oneOf.
				return map[string]any{
					"oneOf": []any{
						map[string]any{"$ref": ref},
						map[string]any{"type": "null"},
					},
				}
			}
			return inner
		}

	case ir.KindRef:
		s["$ref"] = "#/$defs/" + t.RefName
	}

	// Apply constraints.
	for _, c := range t.Constraints {
		s[c.Keyword] = c.Value
	}

	return s
}

// typeRefToSchema converts an IR TypeRef to a JSON Schema.
func typeRefToSchema(ref ir.TypeRef) map[string]any {
	if ref.Name != "" {
		return map[string]any{"$ref": "#/$defs/" + ref.Name}
	}
	if ref.Inline != nil {
		return typeToSchema(ref.Inline, false)
	}
	return map[string]any{}
}

// GoCodegen emits the compschema.gen.go file contents.
// inlinedTypes is the set of type names that were inlined into parent schemas
// and should not get their own methods.
func GoCodegen(pkg *ir.Package, inlinedTypes map[string]bool) string {
	return GoCodegenWithOptions(pkg, inlinedTypes, EmitOptions{})
}

// GoCodegenWithOptions emits the compschema.gen.go file with configurable options.
func GoCodegenWithOptions(pkg *ir.Package, inlinedTypes map[string]bool, opts EmitOptions) string {
	var b strings.Builder

	b.WriteString("// Code generated by compschema. DO NOT EDIT.\n\n")
	b.WriteString(fmt.Sprintf("package %s\n\n", pkg.Name))

	// Check if we need fmt import (discriminated unions).
	needsFmt := false
	for _, name := range pkg.Order {
		if inlinedTypes[name] {
			continue
		}
		t := pkg.Types[name]
		if t.Kind == ir.KindUnion && len(t.Variants) > 0 {
			needsFmt = true
			break
		}
	}

	b.WriteString("import (\n")
	b.WriteString("\t_ \"embed\"\n")
	b.WriteString("\t\"encoding/json\"\n")
	if needsFmt {
		b.WriteString("\t\"fmt\"\n")
	}
	b.WriteString("\t\"sync\"\n\n")
	b.WriteString("\t\"github.com/santhosh-tekuri/jsonschema/v6\"\n")
	b.WriteString(")\n\n")

	// Ptr helper — emit if constructors enabled and any struct has optional pointer fields.
	if opts.Constructors && needsPtrHelper(pkg, inlinedTypes) {
		b.WriteString("// Ptr returns a pointer to v. Useful for setting optional fields on generated types.\n")
		b.WriteString("func Ptr[T any](v T) *T { return &v }\n\n")
	}

	// Embed.
	b.WriteString("//go:embed schema.gen.json\n")
	b.WriteString("var compschemaJSON []byte\n\n")

	// Def cache.
	b.WriteString("var compschemaDefCache sync.Map\n\n")
	b.WriteString("func compschemaDefBytes(name string) json.RawMessage {\n")
	b.WriteString("\tif v, ok := compschemaDefCache.Load(name); ok {\n")
	b.WriteString("\t\treturn v.(json.RawMessage)\n")
	b.WriteString("\t}\n")
	b.WriteString("\tvar full struct {\n")
	b.WriteString("\t\tDefs map[string]json.RawMessage `json:\"$defs\"`\n")
	b.WriteString("\t}\n")
	b.WriteString("\tjson.Unmarshal(compschemaJSON, &full)\n")
	b.WriteString("\tb := full.Defs[name]\n")
	b.WriteString("\tcompschemaDefCache.Store(name, b)\n")
	b.WriteString("\treturn b\n")
	b.WriteString("}\n\n")

	// Per-type compiled validators.
	b.WriteString("var compschemaValidators sync.Map\n\n")
	b.WriteString("func compschemaValidator(name string) *jsonschema.Schema {\n")
	b.WriteString("\tif v, ok := compschemaValidators.Load(name); ok {\n")
	b.WriteString("\t\treturn v.(*jsonschema.Schema)\n")
	b.WriteString("\t}\n")
	b.WriteString("\tc := jsonschema.NewCompiler()\n")
	b.WriteString("\tvar doc any\n")
	b.WriteString("\tif err := json.Unmarshal(compschemaJSON, &doc); err != nil {\n")
	b.WriteString("\t\tpanic(\"compschema: \" + err.Error())\n")
	b.WriteString("\t}\n")
	b.WriteString("\tif err := c.AddResource(\"schema.json\", doc); err != nil {\n")
	b.WriteString("\t\tpanic(\"compschema: \" + err.Error())\n")
	b.WriteString("\t}\n")
	b.WriteString("\tsch, err := c.Compile(\"schema.json#/$defs/\" + name)\n")
	b.WriteString("\tif err != nil {\n")
	b.WriteString("\t\tpanic(\"compschema: \" + err.Error())\n")
	b.WriteString("\t}\n")
	b.WriteString("\tcompschemaValidators.Store(name, sch)\n")
	b.WriteString("\treturn sch\n")
	b.WriteString("}\n\n")

	// Per-type methods.
	for _, name := range pkg.Order {
		if inlinedTypes[name] {
			continue
		}
		t := pkg.Types[name]
		if isAnyType(t) {
			// Any-aliases are interfaces — free function only.
			b.WriteString(fmt.Sprintf("// %sJSONSchemaBytes returns the JSON Schema for the %s type.\n", name, name))
			b.WriteString(fmt.Sprintf("func %sJSONSchemaBytes() json.RawMessage { return compschemaDefBytes(%q) }\n\n", name, name))
			continue
		}
		if t.Kind == ir.KindUnion {
			// Unions are interfaces — JSONSchemaBytes as free function.
			b.WriteString(fmt.Sprintf("// %sJSONSchemaBytes returns the JSON Schema for the %s union.\n", name, name))
			b.WriteString(fmt.Sprintf("func %sJSONSchemaBytes() json.RawMessage { return compschemaDefBytes(%q) }\n\n", name, name))

			// Decode function with discriminator-based switch (if discriminated).
			emitUnionDecode(&b, name, t, pkg)

			// As function — type-safe variant extraction like errors.As.
			emitUnionAs(&b, name)
			continue
		}
		if t.Kind == ir.KindEnum || t.Kind == ir.KindScalar || t.Kind == ir.KindList || t.Kind == ir.KindMap {
			b.WriteString(fmt.Sprintf("// JSONSchemaBytes returns the JSON Schema for %s.\n", name))
			b.WriteString(fmt.Sprintf("func (%s) JSONSchemaBytes() json.RawMessage { return compschemaDefBytes(%q) }\n\n", name, name))
			continue
		}
		if t.Kind != ir.KindStruct {
			continue
		}

		// JSONSchemaBytes
		b.WriteString(fmt.Sprintf("// JSONSchemaBytes returns the JSON Schema definition for %s.\n", name))
		b.WriteString(fmt.Sprintf("func (%s) JSONSchemaBytes() json.RawMessage { return compschemaDefBytes(%q) }\n\n", name, name))

		// Validate
		b.WriteString(fmt.Sprintf("// Validate checks whether raw JSON conforms to the %s schema.\n", name))
		b.WriteString(fmt.Sprintf("func (%s) Validate(data []byte) error {\n", name))
		b.WriteString(fmt.Sprintf("\tsch := compschemaValidator(%q)\n", name))
		b.WriteString("\tvar v any\n")
		b.WriteString("\tif err := json.Unmarshal(data, &v); err != nil {\n")
		b.WriteString("\t\treturn err\n")
		b.WriteString("\t}\n")
		b.WriteString("\treturn sch.Validate(v)\n")
		b.WriteString("}\n\n")

		// Decode
		b.WriteString(fmt.Sprintf("// Decode%s validates and unmarshals JSON into a %s.\n", name, name))
		b.WriteString(fmt.Sprintf("func Decode%s(data []byte) (%s, error) {\n", name, name))
		b.WriteString(fmt.Sprintf("\tvar zero %s\n", name))
		b.WriteString("\tif err := zero.Validate(data); err != nil {\n")
		b.WriteString(fmt.Sprintf("\t\treturn %s{}, err\n", name))
		b.WriteString("\t}\n")
		b.WriteString(fmt.Sprintf("\tvar result %s\n", name))
		b.WriteString("\tif err := json.Unmarshal(data, &result); err != nil {\n")
		b.WriteString(fmt.Sprintf("\t\treturn %s{}, err\n", name))
		b.WriteString("\t}\n")
		b.WriteString("\treturn result, nil\n")
		b.WriteString("}\n\n")

		// Constructor (skip wrapper types — they get union helpers instead)
		if opts.Constructors && !isWrapperType(t) {
			emitConstructor(&b, name, t, pkg)
		}
	}

	// Emit UnmarshalJSON for structs with union-typed fields.
	// json.Unmarshal can't unmarshal into interface fields — we need custom
	// unmarshalers that dispatch to the union's Decode function.
	resolver := newCodegenResolver(pkg)
	unionTypes := make(map[string]bool)
	for _, name := range pkg.Order {
		if inlinedTypes[name] {
			continue
		}
		if pkg.Types[name].Kind == ir.KindUnion {
			unionTypes[name] = true
		}
	}
	for _, name := range pkg.Order {
		if inlinedTypes[name] {
			continue
		}
		t := pkg.Types[name]
		if t.Kind != ir.KindStruct || isAnyType(t) || isWrapperType(t) {
			continue
		}
		if t.HasUnmarshalJSON {
			continue // already has a custom UnmarshalJSON (e.g. from importer)
		}
		emitCodegenUnmarshalJSON(&b, name, t, pkg, resolver, unionTypes)
	}

	return b.String()
}

// needsPtrHelper returns true if any struct type has optional pointer fields,
// meaning the Ptr[T] helper would be useful.
func needsPtrHelper(pkg *ir.Package, inlinedTypes map[string]bool) bool {
	for _, name := range pkg.Order {
		if inlinedTypes[name] {
			continue
		}
		t := pkg.Types[name]
		if t.Kind != ir.KindStruct {
			continue
		}
		for _, f := range t.Fields {
			if !f.Required && isPointerField(f, pkg) {
				return true
			}
		}
	}
	return false
}

// isPointerField returns true if the field's Go representation would be a pointer type.
func isPointerField(f ir.Field, pkg *ir.Package) bool {
	// Check if it's an inline nullable.
	if f.Type.Inline != nil && f.Type.Inline.Kind == ir.KindNullable {
		return true
	}
	// Named type that resolves to nullable.
	if f.Type.Name != "" {
		if t, ok := pkg.Types[f.Type.Name]; ok && t.Kind == ir.KindNullable {
			return true
		}
	}
	return false
}

// constValue returns the const constraint value for a field, or nil if none.
func constValue(f ir.Field) any {
	for _, c := range f.Constraints {
		if c.Keyword == "const" {
			return c.Value
		}
	}
	return nil
}

// defaultValue returns the default constraint value for a field, or nil if none.
func defaultValue(f ir.Field) any {
	for _, c := range f.Constraints {
		if c.Keyword == "default" {
			return c.Value
		}
	}
	return nil
}

// isAutoFilled returns true if the field should be auto-filled in the constructor
// (has a const or default constraint).
func isAutoFilled(f ir.Field) bool {
	return constValue(f) != nil || defaultValue(f) != nil
}

// constructorParams returns the required, non-auto-filled fields in declaration order.
func constructorParams(t *ir.Type) []ir.Field {
	var params []ir.Field
	for _, f := range t.Fields {
		if f.Required && !isAutoFilled(f) {
			params = append(params, f)
		}
	}
	return params
}

// autoFilledFields returns fields that have const or default values.
func autoFilledFields(t *ir.Type) []ir.Field {
	var fields []ir.Field
	for _, f := range t.Fields {
		if isAutoFilled(f) {
			fields = append(fields, f)
		}
	}
	return fields
}

// fieldGoType returns the Go type string for a field's type, suitable for
// use as a constructor parameter.
func fieldGoType(f ir.Field, pkg *ir.Package) string {
	ref := f.Type
	if ref.Name != "" {
		if t, ok := pkg.Types[ref.Name]; ok {
			switch t.Kind {
			case ir.KindEnum:
				return ref.Name
			case ir.KindScalar:
				if t.ScalarType == "any" {
					return "any"
				}
				return ref.Name
			case ir.KindStruct:
				return ref.Name
			case ir.KindUnion:
				return ref.Name
			case ir.KindList:
				return ref.Name
			case ir.KindMap:
				return ref.Name
			case ir.KindNullable:
				// For nullable named types used as required params, unwrap.
				if t.Inner != nil {
					inner := fieldGoTypeFromRef(*t.Inner, pkg)
					return inner
				}
				return ref.Name
			}
		}
		return ref.Name
	}
	if ref.Inline != nil {
		return fieldGoTypeFromInline(ref.Inline, pkg)
	}
	return "any"
}

func fieldGoTypeFromRef(ref ir.TypeRef, pkg *ir.Package) string {
	if ref.Name != "" {
		return ref.Name
	}
	if ref.Inline != nil {
		return fieldGoTypeFromInline(ref.Inline, pkg)
	}
	return "any"
}

func fieldGoTypeFromInline(t *ir.Type, pkg *ir.Package) string {
	switch t.Kind {
	case ir.KindScalar:
		switch t.ScalarType {
		case "string":
			return "string"
		case "integer":
			return "int"
		case "int", "int8", "int16", "int32", "int64":
			return t.ScalarType
		case "number":
			return "float64"
		case "boolean":
			return "bool"
		default:
			return "any"
		}
	case ir.KindList:
		elem := "any"
		if t.Items != nil {
			elem = fieldGoTypeFromRef(*t.Items, pkg)
		}
		return "[]" + elem
	case ir.KindMap:
		val := "any"
		if t.MapValue != nil {
			val = fieldGoTypeFromRef(*t.MapValue, pkg)
		}
		return "map[string]" + val
	case ir.KindNullable:
		if t.Inner != nil {
			inner := fieldGoTypeFromRef(*t.Inner, pkg)
			if strings.HasPrefix(inner, "*") || strings.HasPrefix(inner, "[]") || strings.HasPrefix(inner, "map[") {
				return inner
			}
			return "*" + inner
		}
		return "any"
	case ir.KindRef:
		return t.RefName
	default:
		return "any"
	}
}

// paramName converts a Go field name to a constructor parameter name (camelCase).
// Handles Go keywords by appending an underscore.
func paramName(fieldName string) string {
	if fieldName == "" {
		return "_"
	}
	// Convert first letter to lowercase.
	runes := []rune(fieldName)
	// Find the end of the uppercase prefix (for names like "ID" → "id", "URL" → "url").
	i := 0
	for i < len(runes) && runes[i] >= 'A' && runes[i] <= 'Z' {
		i++
	}
	if i == 0 {
		// Already lowercase.
	} else if i == 1 {
		// Single uppercase letter.
		runes[0] = runes[0] + 32 // toLower
	} else if i == len(runes) {
		// All uppercase (e.g. "ID").
		for j := range runes {
			if runes[j] >= 'A' && runes[j] <= 'Z' {
				runes[j] = runes[j] + 32
			}
		}
	} else {
		// Multiple uppercase then lowercase (e.g. "URLPath" → "urlPath").
		for j := 0; j < i-1; j++ {
			runes[j] = runes[j] + 32
		}
	}
	name := string(runes)

	// Check for Go keywords.
	switch name {
	case "break", "case", "chan", "const", "continue", "default", "defer",
		"else", "fallthrough", "for", "func", "go", "goto", "if", "import",
		"interface", "map", "package", "range", "return", "select", "struct",
		"switch", "type", "var":
		return name + "_"
	}
	return name
}

// goLiteral returns a Go literal string for a const/default value.
func goLiteral(v any) string {
	switch val := v.(type) {
	case string:
		return fmt.Sprintf("%q", val)
	case float64:
		if val == float64(int64(val)) {
			return fmt.Sprintf("%d", int64(val))
		}
		return fmt.Sprintf("%v", val)
	case int:
		return fmt.Sprintf("%d", val)
	case int64:
		return fmt.Sprintf("%d", val)
	case bool:
		if val {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprintf("%v", val)
	}
}

// isNullableRequiredField returns true if the field is required but its Go type
// would be a pointer (e.g., *string from a nullable schema). In this case,
// the constructor should accept the unwrapped type and wrap with &.
func isNullableRequiredField(f ir.Field, pkg *ir.Package) bool {
	if !f.Required {
		return false
	}
	// Check inline nullable.
	if f.Type.Inline != nil && f.Type.Inline.Kind == ir.KindNullable {
		return true
	}
	// Check named nullable type.
	if f.Type.Name != "" {
		if t, ok := pkg.Types[f.Type.Name]; ok && t.Kind == ir.KindNullable {
			return true
		}
	}
	return false
}

// emitConstructor writes a NewT() constructor function for a struct type.
func emitConstructor(b *strings.Builder, name string, t *ir.Type, pkg *ir.Package) {
	params := constructorParams(t)
	autoFilled := autoFilledFields(t)

	// Skip if nothing useful to generate.
	if len(params) == 0 && len(autoFilled) == 0 {
		return
	}

	// Build parameter list.
	var paramParts []string
	for _, f := range params {
		pName := paramName(f.Name)
		pType := fieldGoType(f, pkg)
		// For nullable required fields, the param should be the unwrapped type
		// (the constructor will wrap with & when assigning to the field).
		if isNullableRequiredField(f, pkg) {
			pType = strings.TrimPrefix(pType, "*")
		}
		paramParts = append(paramParts, fmt.Sprintf("%s %s", pName, pType))
	}

	// Comment.
	b.WriteString(fmt.Sprintf("// New%s creates a new %s with required fields and auto-filled const/default values.\n", name, name))
	b.WriteString(fmt.Sprintf("func New%s(%s) *%s {\n", name, strings.Join(paramParts, ", "), name))
	b.WriteString(fmt.Sprintf("\treturn &%s{\n", name))

	// Auto-filled fields first.
	for _, f := range autoFilled {
		val := constValue(f)
		if val == nil {
			val = defaultValue(f)
		}
		b.WriteString(fmt.Sprintf("\t\t%s: %s,\n", f.Name, goLiteral(val)))
	}

	// Required params.
	for _, f := range params {
		pName := paramName(f.Name)
		if isNullableRequiredField(f, pkg) {
			b.WriteString(fmt.Sprintf("\t\t%s: &%s,\n", f.Name, pName))
		} else {
			b.WriteString(fmt.Sprintf("\t\t%s: %s,\n", f.Name, pName))
		}
	}

	b.WriteString("\t}\n")
	b.WriteString("}\n\n")
}

// emitUnionAs generates a generic As function for type-safe variant extraction.
// Uses the pointer constraint pattern so only types implementing the union
// interface can be used as targets — compile-time safety like errors.As.
//
// Generated:
//
//	func ShapeAs[T any, P interface{ *T; Shape }](v Shape, target *T) bool
func emitUnionAs(b *strings.Builder, name string) {
	b.WriteString(fmt.Sprintf("// %sAs extracts a variant from a %s union value, like errors.As.\n", name, name))
	b.WriteString(fmt.Sprintf("// Only types whose pointer implements %s can be used as target (compile-time checked).\n", name))
	b.WriteString("//\n")
	b.WriteString("// Usage:\n")
	b.WriteString("//\n")
	b.WriteString("//\tvar circle Circle\n")
	b.WriteString(fmt.Sprintf("//\tif %sAs(shape, &circle) {\n", name))
	b.WriteString("//\t\t// circle is populated\n")
	b.WriteString("//\t}\n")
	b.WriteString(fmt.Sprintf("func %sAs[T any, P interface{ *T; %s }](v %s, target *T) bool {\n", name, name, name))
	b.WriteString("\tt, ok := v.(P)\n")
	b.WriteString("\tif ok {\n")
	b.WriteString("\t\t*target = *t\n")
	b.WriteString("\t}\n")
	b.WriteString("\treturn ok\n")
	b.WriteString("}\n\n")
}

// emitUnionDecode generates a Decode function for a union type.
// For discriminated unions, generates a switch on the discriminator field.
// For non-discriminated unions, tries each variant in order.
func emitUnionDecode(b *strings.Builder, name string, t *ir.Type, pkg *ir.Package) {
	b.WriteString(fmt.Sprintf("// Decode%s validates and unmarshals JSON into the correct %s variant.\n", name, name))
	if t.Discriminator != "" {
		b.WriteString(fmt.Sprintf("// Dispatches on the %q discriminator field.\n", t.Discriminator))
	}
	b.WriteString(fmt.Sprintf("func Decode%s(data []byte) (%s, error) {\n", name, name))

	// Validate against schema first.
	b.WriteString(fmt.Sprintf("\tsch := compschemaValidator(%q)\n", name))
	b.WriteString("\tvar raw any\n")
	b.WriteString("\tif err := json.Unmarshal(data, &raw); err != nil {\n")
	b.WriteString("\t\treturn nil, err\n")
	b.WriteString("\t}\n")
	b.WriteString("\tif err := sch.Validate(raw); err != nil {\n")
	b.WriteString("\t\treturn nil, err\n")
	b.WriteString("\t}\n")

	if t.Discriminator != "" && hasDiscriminatorValues(t) {
		// Discriminator-based switch.
		b.WriteString(fmt.Sprintf("\tvar disc struct {\n\t\tD string `json:%q`\n\t}\n", t.Discriminator))
		b.WriteString("\tif err := json.Unmarshal(data, &disc); err != nil {\n")
		b.WriteString("\t\treturn nil, err\n")
		b.WriteString("\t}\n")
		b.WriteString("\tswitch disc.D {\n")

		emitted := map[string]bool{}
		for _, v := range t.Variants {
			if len(v.DiscriminatorValues) == 0 || emitted[v.DiscriminatorValues[0]] {
				continue
			}
			for _, dv := range v.DiscriminatorValues {
				emitted[dv] = true
			}
			variantType := v.Name
			if variantType == "" {
				continue
			}
			// Check if variant is a struct (can take address).
			if vt, ok := pkg.Types[variantType]; ok && vt.Kind != ir.KindStruct {
				continue
			}
			// Build case label with all values.
			var caseValues []string
			for _, dv := range v.DiscriminatorValues {
				caseValues = append(caseValues, fmt.Sprintf("%q", dv))
			}
			b.WriteString(fmt.Sprintf("\tcase %s:\n", strings.Join(caseValues, ", ")))
			b.WriteString(fmt.Sprintf("\t\tvar val %s\n", variantType))
			b.WriteString("\t\tif err := json.Unmarshal(data, &val); err != nil {\n")
			b.WriteString("\t\t\treturn nil, err\n")
			b.WriteString("\t\t}\n")
			b.WriteString("\t\treturn &val, nil\n")
		}
		b.WriteString(fmt.Sprintf("\tdefault:\n\t\treturn nil, fmt.Errorf(\"unknown %s %%q for %s\", disc.D)\n", t.Discriminator, name))
		b.WriteString("\t}\n")
	} else {
		// No discriminator — match on required property sets.
		// Extract the JSON keys present in the input, then try variants
		// sorted by specificity (most required fields first).
		var candidates []variantReq
		for _, v := range t.Variants {
			if v.Name == "" {
				continue
			}
			vt, ok := pkg.Types[v.Name]
			if !ok || vt.Kind != ir.KindStruct {
				continue
			}
			var req []string
			for _, f := range vt.Fields {
				if f.Required {
					req = append(req, f.JSONName)
				}
			}
			candidates = append(candidates, variantReq{v.Name, req})
		}

		if len(candidates) > 0 && hasDistinctRequiredSets(candidates) {
			// Sort by specificity (most required fields first).
			b.WriteString("\tvar keys map[string]bool\n")
			b.WriteString("\t{\n")
			b.WriteString("\t\tvar obj map[string]json.RawMessage\n")
			b.WriteString("\t\tif err := json.Unmarshal(data, &obj); err == nil {\n")
			b.WriteString("\t\t\tkeys = make(map[string]bool, len(obj))\n")
			b.WriteString("\t\t\tfor k := range obj {\n")
			b.WriteString("\t\t\t\tkeys[k] = true\n")
			b.WriteString("\t\t\t}\n")
			b.WriteString("\t\t}\n")
			b.WriteString("\t}\n")

			// Sort candidates: most required fields first for specificity.
			sort.Slice(candidates, func(i, j int) bool {
				return len(candidates[i].required) > len(candidates[j].required)
			})

			for _, c := range candidates {
				if len(c.required) == 0 {
					// No required fields — always matches, use as last resort.
					continue
				}
				// Check if all required fields are present.
				var checks []string
				for _, r := range c.required {
					checks = append(checks, fmt.Sprintf("keys[%q]", r))
				}
				b.WriteString(fmt.Sprintf("\tif %s {\n", strings.Join(checks, " && ")))
				b.WriteString(fmt.Sprintf("\t\tvar val %s\n", c.name))
				b.WriteString("\t\tif err := json.Unmarshal(data, &val); err == nil {\n")
				b.WriteString("\t\t\treturn &val, nil\n")
				b.WriteString("\t\t}\n")
				b.WriteString("\t}\n")
			}

			// Fallback: try variants with no required fields.
			for _, c := range candidates {
				if len(c.required) > 0 {
					continue
				}
				b.WriteString(fmt.Sprintf("\t{\n\t\tvar val %s\n", c.name))
				b.WriteString("\t\tif err := json.Unmarshal(data, &val); err == nil {\n")
				b.WriteString("\t\t\treturn &val, nil\n")
				b.WriteString("\t\t}\n")
				b.WriteString("\t}\n")
			}
		} else {
			// Truly ambiguous — brute force try each.
			for _, c := range candidates {
				b.WriteString(fmt.Sprintf("\t{\n\t\tvar val %s\n", c.name))
				b.WriteString("\t\tif err := json.Unmarshal(data, &val); err == nil {\n")
				b.WriteString("\t\t\treturn &val, nil\n")
				b.WriteString("\t\t}\n")
				b.WriteString("\t}\n")
			}
		}
		b.WriteString(fmt.Sprintf("\treturn nil, fmt.Errorf(\"no matching variant for %s\")\n", name))
	}

	b.WriteString("}\n\n")
}

// variantReq pairs a variant name with its required JSON fields.
type variantReq struct {
	name     string
	required []string
}

// hasDistinctRequiredSets checks if at least some variants have unique required
// property sets that can be used for structural discrimination.
func hasDistinctRequiredSets(candidates []variantReq) bool {
	seen := make(map[string]int)
	for _, c := range candidates {
		if len(c.required) == 0 {
			continue
		}
		sorted := make([]string, len(c.required))
		copy(sorted, c.required)
		sort.Strings(sorted)
		k := strings.Join(sorted, ",")
		seen[k]++
	}
	return len(seen) >= 2
}

// hasDiscriminatorValues returns true if at least one variant has a discriminator value.
func hasDiscriminatorValues(t *ir.Type) bool {
	for _, v := range t.Variants {
		if v.HasDiscriminator() {
			return true
		}
	}
	return false
}

// GoTests emits the compschema_test.gen.go file contents.
func GoTests(pkg *ir.Package, inlinedTypes map[string]bool) string {
	return GoTestsWithOptions(pkg, inlinedTypes, EmitOptions{})
}

// GoTestsWithOptions emits tests with configurable options.
func GoTestsWithOptions(pkg *ir.Package, inlinedTypes map[string]bool, opts EmitOptions) string {
	var b strings.Builder

	b.WriteString("// Code generated by compschema. DO NOT EDIT.\n\n")
	b.WriteString(fmt.Sprintf("package %s\n\n", pkg.Name))
	b.WriteString("import (\n")
	b.WriteString("\t\"encoding/json\"\n")
	b.WriteString("\t\"testing\"\n")
	b.WriteString(")\n\n")

	// Package-level tests.
	b.WriteString("func TestCompschema_SchemaIsValidJSON(t *testing.T) {\n")
	b.WriteString("\tvar v any\n")
	b.WriteString("\tif err := json.Unmarshal(compschemaJSON, &v); err != nil {\n")
	b.WriteString("\t\tt.Fatalf(\"schema.gen.json is not valid JSON: %v\", err)\n")
	b.WriteString("\t}\n")
	b.WriteString("}\n\n")

	// Per-type tests.
	for _, name := range pkg.Order {
		if inlinedTypes[name] {
			continue
		}
		t := pkg.Types[name]

		// Skip any-typed aliases — can't instantiate or call methods on them.
		if isAnyType(t) {
			continue
		}

		// Skip pointer alias types (KindNullable at top level, e.g. type Foo *string)
		// — can't composite-literal or call methods on them.
		if t.Kind == ir.KindNullable {
			continue
		}

		// JSONSchemaBytes test — for all types.
		b.WriteString(fmt.Sprintf("func TestCompschema_%s_JSONSchemaBytes(t *testing.T) {\n", name))
		switch t.Kind {
		case ir.KindUnion:
			b.WriteString(fmt.Sprintf("\tb := %sJSONSchemaBytes()\n", name))
		case ir.KindEnum, ir.KindScalar:
			b.WriteString(fmt.Sprintf("\tb := %s(\"\").JSONSchemaBytes()\n", name))
		default:
			b.WriteString(fmt.Sprintf("\tb := (%s{}).JSONSchemaBytes()\n", name))
		}
		b.WriteString("\tif len(b) == 0 {\n")
		b.WriteString("\t\tt.Fatal(\"JSONSchemaBytes returned empty\")\n")
		b.WriteString("\t}\n")
		b.WriteString("\tvar v any\n")
		b.WriteString("\tif err := json.Unmarshal(b, &v); err != nil {\n")
		b.WriteString("\t\tt.Fatalf(\"JSONSchemaBytes is not valid JSON: %v\", err)\n")
		b.WriteString("\t}\n")
		b.WriteString("}\n\n")

		if t.Kind != ir.KindStruct {
			continue
		}

		// Scalar wrapper types emit as their inner scalar type, not as objects.
		scalarWrap := isWrapperType(t) && isScalarWrapper(t)

		// Validate rejects invalid JSON.
		b.WriteString(fmt.Sprintf("func TestCompschema_%s_ValidateRejectsInvalidJSON(t *testing.T) {\n", name))
		b.WriteString(fmt.Sprintf("\terr := (%s{}).Validate([]byte(`{not json}`))\n", name))
		b.WriteString("\tif err == nil {\n")
		b.WriteString("\t\tt.Fatal(\"Validate should reject invalid JSON\")\n")
		b.WriteString("\t}\n")
		b.WriteString("}\n\n")

		// Validate rejects wrong type (skip for scalar wrappers — they ARE scalars).
		if !scalarWrap {
			b.WriteString(fmt.Sprintf("func TestCompschema_%s_ValidateRejectsWrongType(t *testing.T) {\n", name))
			b.WriteString(fmt.Sprintf("\terr := (%s{}).Validate([]byte(`\"a string\"`))\n", name))
			b.WriteString("\tif err == nil {\n")
			b.WriteString(fmt.Sprintf("\t\tt.Fatal(\"%s.Validate should reject a string for an object type\")\n", name))
			b.WriteString("\t}\n")
			b.WriteString("}\n\n")
		}

		// Validate rejects empty object (if type has required fields, non-scalar-wrapper).
		if t.HasRequired() && !scalarWrap {
			b.WriteString(fmt.Sprintf("func TestCompschema_%s_ValidateRejectsEmpty(t *testing.T) {\n", name))
			b.WriteString(fmt.Sprintf("\terr := (%s{}).Validate([]byte(`{}`))\n", name))
			b.WriteString("\tif err == nil {\n")
			b.WriteString(fmt.Sprintf("\t\tt.Fatal(\"%s.Validate({}) should fail (has required fields)\")\n", name))
			b.WriteString("\t}\n")
			b.WriteString("}\n\n")
		}

		// Round-trip test.
		b.WriteString(fmt.Sprintf("func TestCompschema_%s_RoundTrip(t *testing.T) {\n", name))
		fixture, feasible := generateFixture(t, pkg)
		if !feasible {
			b.WriteString("\tt.Skip(\"type has fields with union/interface types that cannot be auto-fixtured\")\n")
		} else if fixture == "" {
			b.WriteString("\tt.Skip(\"auto-generated fixture not available for this type\")\n")
		} else {
			b.WriteString(fmt.Sprintf("\tdata := []byte(`%s`)\n", fixture))
			b.WriteString(fmt.Sprintf("\tresult, err := Decode%s(data)\n", name))
			b.WriteString("\tif err != nil {\n")
			b.WriteString("\t\tt.Fatalf(\"Decode: %v\", err)\n")
			b.WriteString("\t}\n")
			b.WriteString("\treencoded, err := json.Marshal(result)\n")
			b.WriteString("\tif err != nil {\n")
			b.WriteString("\t\tt.Fatalf(\"re-marshal: %v\", err)\n")
			b.WriteString("\t}\n")
			b.WriteString("\t_ = reencoded // round-trip succeeded\n")
		}
		b.WriteString("}\n\n")
	}

	// Example validation + decode tests — table-driven, covering all types.
	if opts.Examples {
		b.WriteString("func TestCompschema_ExamplesValidate(t *testing.T) {\n")
		b.WriteString("\ttests := []struct {\n")
		b.WriteString("\t\tname    string\n")
		b.WriteString("\t\texample string\n")
		b.WriteString("\t}{\n")

		// Collect types that have examples.
		type exEntry struct {
			name string
			json string
			t    *ir.Type
		}
		var entries []exEntry

		for _, name := range pkg.Order {
			if inlinedTypes[name] {
				continue
			}
			t := pkg.Types[name]
			if isAnyType(t) {
				continue
			}

			ex := GenerateExample(t, pkg)
			if ex == nil {
				continue
			}
			exJSON, err := json.Marshal(ex)
			if err != nil {
				continue
			}
			exStr := strings.ReplaceAll(string(exJSON), "`", "`+\"`\"+`")
			b.WriteString(fmt.Sprintf("\t\t{%q, `%s`},\n", name, exStr))
			entries = append(entries, exEntry{name, string(exJSON), t})
		}

		b.WriteString("\t}\n")
		b.WriteString("\tfor _, tt := range tests {\n")
		b.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		b.WriteString("\t\t\t// Verify example is valid JSON.\n")
		b.WriteString("\t\t\tvar v any\n")
		b.WriteString("\t\t\tif err := json.Unmarshal([]byte(tt.example), &v); err != nil {\n")
		b.WriteString("\t\t\t\tt.Fatalf(\"example is not valid JSON: %v\", err)\n")
		b.WriteString("\t\t\t}\n")
		b.WriteString("\t\t\t// Validate against schema.\n")
		b.WriteString("\t\t\tsch := compschemaValidator(tt.name)\n")
		b.WriteString("\t\t\tif err := sch.Validate(v); err != nil {\n")
		b.WriteString("\t\t\t\tt.Errorf(\"example failed validation: %v\", err)\n")
		b.WriteString("\t\t\t}\n")
		b.WriteString("\t\t})\n")
		b.WriteString("\t}\n")
		b.WriteString("}\n\n")

		// Decode tests — one sub-test per type calling DecodeX.
		b.WriteString("func TestCompschema_ExamplesDecode(t *testing.T) {\n")
		for _, e := range entries {
			exStr := strings.ReplaceAll(e.json, "`", "`+\"`\"+`")
			b.WriteString(fmt.Sprintf("\tt.Run(%q, func(t *testing.T) {\n", e.name))
			b.WriteString(fmt.Sprintf("\t\tdata := []byte(`%s`)\n", exStr))

			switch e.t.Kind {
			case ir.KindStruct:
				if isWrapperType(e.t) {
					b.WriteString("\t\t_ = data // wrapper type, skip decode\n")
				} else {
					b.WriteString(fmt.Sprintf("\t\tresult, err := Decode%s(data)\n", e.name))
					b.WriteString("\t\tif err != nil {\n")
					b.WriteString("\t\t\tt.Fatalf(\"Decode: %v\", err)\n")
					b.WriteString("\t\t}\n")
					b.WriteString("\t\treencoded, err := json.Marshal(result)\n")
					b.WriteString("\t\tif err != nil {\n")
					b.WriteString("\t\t\tt.Fatalf(\"re-marshal: %v\", err)\n")
					b.WriteString("\t\t}\n")
					b.WriteString("\t\t_ = reencoded\n")
				}
			case ir.KindUnion:
				b.WriteString(fmt.Sprintf("\t\tresult, err := Decode%s(data)\n", e.name))
				b.WriteString("\t\tif err != nil {\n")
				b.WriteString("\t\t\tt.Fatalf(\"Decode: %v\", err)\n")
				b.WriteString("\t\t}\n")
				b.WriteString("\t\tif result == nil {\n")
				b.WriteString("\t\t\tt.Fatal(\"Decode returned nil\")\n")
				b.WriteString("\t\t}\n")
			default:
				// Enum, scalar, etc. — no Decode function.
				b.WriteString("\t\t_ = data\n")
			}

			b.WriteString("\t})\n")
		}
		b.WriteString("}\n\n")
	}

	// Constructor tests.
	if opts.Constructors {
		for _, name := range pkg.Order {
			if inlinedTypes[name] {
				continue
			}
			t := pkg.Types[name]
			if t.Kind != ir.KindStruct || isWrapperType(t) {
				continue
			}
			params := constructorParams(t)
			autoFilled := autoFilledFields(t)
			if len(params) == 0 && len(autoFilled) == 0 {
				continue
			}
			emitConstructorTest(&b, name, t, pkg)
		}
	}

	return b.String()
}

// emitConstructorTest writes a test for a generated constructor.
func emitConstructorTest(b *strings.Builder, name string, t *ir.Type, pkg *ir.Package) {
	params := constructorParams(t)
	autoFilled := autoFilledFields(t)

	// Check if any param is a union type or has constraints that zero values
	// won't satisfy — skip validation for these.
	hasComplexParam := false
	for _, f := range params {
		if isUnionTypedField(f, pkg) {
			hasComplexParam = true
			break
		}
		// Check for constraints that zero values fail.
		for _, c := range f.Constraints {
			switch c.Keyword {
			case "minLength", "minItems", "pattern":
				if n, ok := toFloat(c.Value); ok && n > 0 {
					hasComplexParam = true
				}
				if c.Keyword == "pattern" {
					hasComplexParam = true
				}
			case "minimum":
				if n, ok := toFloat(c.Value); ok && n > 0 {
					hasComplexParam = true
				}
			}
		}
		if hasComplexParam {
			break
		}
		// Check if the field references a struct with required/const fields
		// (zero value won't be schema-valid).
		if f.Type.Name != "" {
			if ft, ok := pkg.Types[f.Type.Name]; ok && ft.Kind == ir.KindStruct {
				if ft.HasRequired() {
					hasComplexParam = true
				}
			}
		}
		if hasComplexParam {
			break
		}
	}

	b.WriteString(fmt.Sprintf("func TestCompschema_New%s(t *testing.T) {\n", name))

	// Build constructor call with zero/example values.
	var argParts []string
	for _, f := range params {
		argParts = append(argParts, constructorTestArg(f, pkg))
	}

	b.WriteString(fmt.Sprintf("\tv := New%s(%s)\n", name, strings.Join(argParts, ", ")))
	b.WriteString("\tif v == nil {\n")
	b.WriteString(fmt.Sprintf("\t\tt.Fatal(\"New%s returned nil\")\n", name))
	b.WriteString("\t}\n")

	// Check auto-filled fields.
	for _, f := range autoFilled {
		val := constValue(f)
		if val == nil {
			val = defaultValue(f)
		}
		if s, ok := val.(string); ok {
			b.WriteString(fmt.Sprintf("\tif v.%s != %q {\n", f.Name, s))
			b.WriteString(fmt.Sprintf("\t\tt.Errorf(\"%s = %%q, want %%q\", v.%s, %q)\n", f.Name, f.Name, s))
			b.WriteString("\t}\n")
		}
	}

	// Validate round-trip: marshal and validate against schema.
	// Skip validation when params include union types — zero-value variants
	// typically don't satisfy oneOf constraints.
	if hasComplexParam {
		b.WriteString("\t// Skip validation: constructor has union-typed params whose zero values\n")
		b.WriteString("\t// may not satisfy oneOf schema constraints.\n")
	} else {
		b.WriteString("\tdata, err := json.Marshal(v)\n")
		b.WriteString("\tif err != nil {\n")
		b.WriteString("\t\tt.Fatalf(\"marshal: %v\", err)\n")
		b.WriteString("\t}\n")
		b.WriteString("\tif err := v.Validate(data); err != nil {\n")
		b.WriteString(fmt.Sprintf("\t\tt.Errorf(\"New%s output fails validation: %%v\", err)\n", name))
		b.WriteString("\t}\n")
	}

	b.WriteString("}\n\n")
}

// isUnionTypedField returns true if the field's type (directly or through
// lists/nullable wrappers) involves a union interface.
func isUnionTypedField(f ir.Field, pkg *ir.Package) bool {
	return isUnionTypeRef(f.Type, pkg)
}

func isUnionTypeRef(ref ir.TypeRef, pkg *ir.Package) bool {
	if ref.Name != "" {
		if t, ok := pkg.Types[ref.Name]; ok {
			if t.Kind == ir.KindUnion {
				return true
			}
			// Named list whose items are a union.
			if t.Kind == ir.KindList && t.Items != nil {
				return isUnionTypeRef(*t.Items, pkg)
			}
		}
	}
	if ref.Inline != nil {
		if ref.Inline.Kind == ir.KindNullable && ref.Inline.Inner != nil {
			return isUnionTypeRef(*ref.Inline.Inner, pkg)
		}
		if ref.Inline.Kind == ir.KindList && ref.Inline.Items != nil {
			return isUnionTypeRef(*ref.Inline.Items, pkg)
		}
	}
	return false
}

// constructorTestArg returns a Go expression for a constructor test argument.
func constructorTestArg(f ir.Field, pkg *ir.Package) string {
	// Use const value if available.
	if v := constValue(f); v != nil {
		return goLiteral(v)
	}

	// Check constraints for a useful value.
	for _, c := range f.Constraints {
		if c.Keyword == "minimum" {
			if n, ok := toFloat(c.Value); ok {
				if n == float64(int64(n)) {
					return fmt.Sprintf("%d", int64(n))
				}
				return fmt.Sprintf("%v", n)
			}
		}
	}

	// Generate zero-ish value based on type.
	return constructorTestArgFromType(f.Type, pkg)
}

func constructorTestArgFromType(ref ir.TypeRef, pkg *ir.Package) string {
	if ref.Name != "" {
		if t, ok := pkg.Types[ref.Name]; ok {
			switch t.Kind {
			case ir.KindEnum:
				if len(t.EnumValues) > 0 {
					return ref.Name + "(" + goLiteral(t.EnumValues[0]) + ")"
				}
				return ref.Name + `("")`
			case ir.KindStruct:
				return ref.Name + "{}"
			case ir.KindUnion:
				// Pick the first struct variant to construct a valid value.
				for _, v := range t.Variants {
					if v.Name != "" {
						if vt, ok := pkg.Types[v.Name]; ok && vt.Kind == ir.KindStruct {
							return "&" + v.Name + "{}"
						}
					}
				}
				return "nil"
			case ir.KindScalar:
				switch t.ScalarType {
				case "string":
					return `""`
				case "integer", "int", "int8", "int16", "int32", "int64":
					return "0"
				case "number":
					return "0.0"
				case "boolean":
					return "false"
				default:
					return "nil"
				}
			case ir.KindList:
				return ref.Name + "{}"
			case ir.KindMap:
				return ref.Name + "{}"
			case ir.KindNullable:
				if t.Inner != nil {
					return constructorTestArgFromType(*t.Inner, pkg)
				}
				return "nil"
			}
		}
		return ref.Name + "{}"
	}
	if ref.Inline != nil {
		switch ref.Inline.Kind {
		case ir.KindScalar:
			switch ref.Inline.ScalarType {
			case "string":
				return `""`
			case "integer", "int", "int8", "int16", "int32", "int64":
				return "0"
			case "number":
				return "0.0"
			case "boolean":
				return "false"
			default:
				return "nil"
			}
		case ir.KindList:
			if ref.Inline.Items != nil {
				item := constructorTestArgFromType(*ref.Inline.Items, pkg)
				return "[]" + fieldGoTypeFromRef(*ref.Inline.Items, pkg) + "{" + item + "}"
			}
			return "[]any{}"
		case ir.KindMap:
			if ref.Inline.MapValue != nil {
				return "map[string]" + fieldGoTypeFromRef(*ref.Inline.MapValue, pkg) + "{}"
			}
			return "map[string]any{}"
		case ir.KindNullable:
			if ref.Inline.Inner != nil {
				return constructorTestArgFromType(*ref.Inline.Inner, pkg)
			}
			return "nil"
		}
	}
	return `""`
}

// generateFixture creates a minimal valid JSON string for a struct type.
// Returns the JSON string and whether the fixture is feasible (no interface{} fields).
func generateFixture(t *ir.Type, pkg *ir.Package) (string, bool) {
	if t.Kind != ir.KindStruct {
		return "", false
	}

	// Wrapper types (single "Value" field with MarshalJSON) serialize as their
	// inner value, not as a JSON object — skip round-trip auto-fixture.
	if isWrapperType(t) {
		return "", false
	}

	visiting := make(map[string]bool)
	feasible := true
	fields := make(map[string]any)
	for _, f := range t.Fields {
		if !f.Required {
			continue
		}
		val, ok := fieldZeroValue(f, pkg, visiting)
		if !ok {
			feasible = false
		}
		fields[f.JSONName] = val
	}

	b, err := json.Marshal(fields)
	if err != nil {
		return "", false
	}
	return string(b), feasible
}

// fieldZeroValue produces a minimal valid value for a field.
func fieldZeroValue(f ir.Field, pkg *ir.Package, visiting map[string]bool) (any, bool) {
	// Check for const constraint.
	for _, c := range f.Constraints {
		if c.Keyword == "const" {
			return c.Value, true
		}
	}

	val, feasible := typeRefZeroValue(f.Type, pkg, visiting)

	// Apply constraints to adjust the zero value.
	for _, c := range f.Constraints {
		switch c.Keyword {
		case "minimum":
			if min, ok := toFloat(c.Value); ok {
				if cur, ok := toFloat(val); ok && cur < min {
					if min == float64(int64(min)) {
						val = int64(min)
					} else {
						val = min
					}
				}
			}
		case "minLength":
			if ml, ok := toFloat(c.Value); ok && ml > 0 {
				if s, ok := val.(string); ok && len(s) < int(ml) {
					val = strings.Repeat("x", int(ml))
				}
			}
		case "pattern":
			if _, ok := val.(string); ok {
				p := fmt.Sprintf("%v", c.Value)
				if strings.Contains(p, "[A-Z]") && strings.Contains(p, "[0-9]") {
					val = "AAA-000"
				} else {
					val = "test"
				}
			}
		case "minItems":
			if mi, ok := toFloat(c.Value); ok && mi > 0 {
				if arr, ok := val.([]any); ok && len(arr) < int(mi) {
					for len(arr) < int(mi) {
						if len(arr) > 0 {
							arr = append(arr, arr[0])
						} else {
							arr = append(arr, nil)
						}
					}
					val = arr
				}
			}
		}
	}

	return val, feasible
}

func toFloat(v any) (float64, bool) {
	switch n := v.(type) {
	case int:
		return float64(n), true
	case int64:
		return float64(n), true
	case float64:
		return n, true
	case json.Number:
		f, err := n.Float64()
		return f, err == nil
	}
	return 0, false
}

func typeRefZeroValue(ref ir.TypeRef, pkg *ir.Package, visiting map[string]bool) (any, bool) {
	if ref.Name != "" {
		if visiting[ref.Name] {
			return nil, false // cycle detected
		}
		visiting[ref.Name] = true
		defer func() { delete(visiting, ref.Name) }()

		if t, ok := pkg.Types[ref.Name]; ok {
			switch t.Kind {
			case ir.KindEnum:
				if len(t.EnumValues) > 0 {
					return t.EnumValues[0], true
				}
				return "", true
			case ir.KindStruct:
				fields := make(map[string]any)
				feasible := true
				for _, f := range t.Fields {
					if f.Required {
						v, ok := fieldZeroValue(f, pkg, visiting)
						if !ok {
							feasible = false
						}
						fields[f.JSONName] = v
					}
				}
				return fields, feasible
			case ir.KindUnion:
				// Can't auto-generate a valid union variant.
				return "", false
			case ir.KindScalar:
				if t.ScalarType == "any" {
					return nil, false
				}
				return scalarZero(t.ScalarType), true
			case ir.KindMap:
				return map[string]any{}, true
			case ir.KindList:
				return []any{}, true
			}
		}
		return nil, false // type not in IR, can't generate fixture
	}

	if ref.Inline == nil {
		return "", true
	}

	switch ref.Inline.Kind {
	case ir.KindScalar:
		if ref.Inline.ScalarType == "any" {
			return nil, false // interface{} — can't generate valid fixture
		}
		return scalarZero(ref.Inline.ScalarType), true
	case ir.KindList:
		if ref.Inline.Items != nil {
			item, ok := typeRefZeroValue(*ref.Inline.Items, pkg, visiting)
			return []any{item}, ok
		}
		return []any{}, true
	case ir.KindNullable:
		if ref.Inline.Inner != nil {
			return typeRefZeroValue(*ref.Inline.Inner, pkg, visiting)
		}
		return nil, true
	case ir.KindMap:
		return map[string]any{}, true
	default:
		return "", true
	}
}

func scalarZero(t string) any {
	switch t {
	case "string":
		return ""
	case "integer", "int", "int8", "int16", "int32", "int64":
		return 0
	case "number":
		return 0.0
	case "boolean":
		return false
	default:
		return ""
	}
}
